    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return grid[0][0]

        prev = grid[0]
        for i in range(1, n):
            # Find the two smallest values (and their indices) in previous row.
            m1 = m2 = float('inf')
            idx1 = -1
            for k, v in enumerate(prev):
                if v < m1:
                    m2 = m1
                    m1 = v
                    idx1 = k
                elif v < m2:
                    m2 = v

            row = grid[i]
            cur = [0] * n
            for j in range(n):
                cur[j] = row[j] + (m2 if j == idx1 else m1)
            prev = cur

        return min(prev)
