class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1]

        for j in range(1, n + 1):
            # Build prefix sums of current dp (length j)
            prefix = [0] * (j + 1)
            for k in range(j):
                prefix[k + 1] = (prefix[k] + dp[k]) % MOD

            new_dp = [0] * (j + 1)
            if s[j - 1] == 'I':
                # new_dp[i] = sum(dp[k] for k in range(i)) = prefix[i]
                for i in range(j + 1):
                    new_dp[i] = prefix[i]
            else:
                # new_dp[i] = sum(dp[k] for k in range(i, j)) = prefix[j] - prefix[i]
                total = prefix[j]
                for i in range(j + 1):
                    new_dp[i] = (total - prefix[i]) % MOD

            dp = new_dp

        return sum(dp) % MOD
```

**Key optimization:** Replaced the inner `sum()` calls (each O(n)) with precomputed prefix sums (O(n) once per outer iteration), reducing overall complexity from **O(n³)** to **O(n²)**.

