    def readBinaryWatch(self, turnedOn: int) -> List[str]:
        if turnedOn > 8 or turnedOn < 0:
            return []

        # Precompute bit counts for hours (0-11) and minutes (0-59)
        hour_bits = [bin(h).count('1') for h in range(12)]
        min_bits = [bin(m).count('1') for m in range(60)]

        # Group hours by their bit count
