        for m in range(60):
            mins_by_count[min_bits[m]].append(f"{m:02}")

        result = []
        for hb in range(min(turnedOn + 1, 4)):
            mb = turnedOn - hb
            if mb < 0 or mb >= 6:
                continue
            for hs in hours_by_count[hb]:
                for ms in mins_by_count[mb]:
                    result.append(hs + ":" + ms)
        return result
